const pendingData = $('2. Lấy Yêu Cầu Thanh Toán Chờ Duyệt').first().json;
const bankData = $input.first().json;

const pending = (pendingData.requests || []).filter(r => r.transferCode && r.status === 'pending' && Number(r.amount) > 0);
const transactions = bankData.transactions || [];

function normalize(str) {
  return (str || '').toUpperCase().replace(/\s+/g, '').replace(/[^A-Z0-9]/g, '');
}

const matchedList = [];

for (const req of pending) {
  const reqCode = normalize(req.transferCode);
  for (const tx of transactions) {
    const txContent = normalize(tx.content || tx.description || '');
    if (!reqCode || !txContent.includes(reqCode)) continue;

    const expAmount = Number(req.amount);
    const actAmount = Number(tx.amount);
    const diff = Math.abs(expAmount - actAmount);
    const tolerance = Math.max(expAmount * 0.05, 10000);

    if (diff <= tolerance) {
      matchedList.push({
        requestId: req.id,
        ownerId: req.ownerId,
        userEmail: req.userEmail,
        planId: req.planId,
        planName: req.planName || req.planId,
        amount: expAmount,
        matchedAmount: actAmount,
        transferCode: req.transferCode,
        durationDays: req.durationDays || null,
        durationMonths: req.durationMonths || null,
        matchConfidence: 'n8n_nexus_autopilot'
      });
      break;
    }
  }
}

return matchedList.map(item => ({ json: item }));

const res = $input.first().json;
const allSettings = res.data || (Array.isArray(res) ? res : []);
const now = new Date();

const toLock = [];

for (const s of allSettings) {
  if (!s.id) continue;

  let expireDate = null;
  if (s.subscriptionExpiresAt) {
    expireDate = new Date(s.subscriptionExpiresAt);
  }

  // Nếu có ngày hết hạn và ngày hết hạn nhỏ hơn hiện tại (đã quá hạn)
  if (expireDate && !isNaN(expireDate.getTime()) && expireDate < now) {
    // Kiểm tra xem hiện tại có đang mở nút nào không, nếu chưa khoá thì đưa vào danh sách đóng nút
    const isCurrentlyUnlocked = !s.manualLockOrders || !s.manualLockDebts || !s.manualLockSheets || s.isPro === true;
    if (isCurrentlyUnlocked) {
      toLock.push({
        ownerId: s.id,
        planId: s.planId || 'free',
        expireDate: expireDate.toISOString(),
        daysExpired: Math.floor((now.getTime() - expireDate.getTime()) / (1000 * 60 * 60 * 24))
      });
    }
  }
}

return toLock.map(item => ({ json: item }));
